  reanalyzeStatus_pending: { zh: '尚未发生', en: 'not happened yet' },
  notifyDone: { zh: '回复完成时提醒', en: 'Alert when a reply is ready' },
  notifyDoneTip: { zh: '回合在后台结束时（你切到了别的标签页或程序）：发系统通知，并在标签页标题前加上“✓ 回复完成”，回到页面后自动去掉。\n回合失败时同样提醒。浏览器只在 https 或 localhost 下允许系统通知；用局域网 http 地址打开时只有标题提示和提示音。', en: 'When a turn ends while the tab is in the background (you switched to another tab or app): a system notification, and "✓ Reply ready" in front of the tab title until you come back.\nAlso when a turn fails. Browsers allow system notifications only on https or localhost; on a LAN http address you get the title mark and the chime only.' },
  notifySound: { zh: '提醒时响一声', en: 'Chime with the alert' },
  notifySoundTip: { zh: '提醒时播放一声短促的提示音（成功高音，失败低音）。', en: 'Play a short chime with the alert (rising when the reply is ready, falling when the turn failed).' },
  notifyInsecure: { zh: '当前地址不是 https 或 localhost，浏览器不允许系统通知：只会改标签页标题并响一声。想要系统通知：用 https 打开酒馆；或在 Chrome 地址栏打开下面的设置页，把酒馆地址填进去，选 Enabled，然后重启 Chrome（网页无法直接打开 chrome:// 页面，请复制后粘贴到地址栏）。', en: 'This address is not https or localhost, so the browser does not allow system notifications: you get the title mark and the chime only. For system notifications, open SillyTavern over https; or open the Chrome settings page below, add the SillyTavern address, choose Enabled and relaunch Chrome (web pages cannot open chrome:// pages: copy it and paste it into the address bar).' },
  notifyFlagPage: { zh: '设置页', en: 'Settings page' },
  notifyFlagValue: { zh: '要填的地址', en: 'Address to add' },
  notifyBlocked: { zh: '浏览器已拒绝本站的通知：在地址栏左侧的网站设置里允许“通知”。', en: 'The browser blocks notifications for this site: allow "Notifications" in the site settings (left of the address bar).' },
  notifyTitleOk: { zh: 'Canon：回复完成', en: 'Canon: reply ready' },
  notifyTitleFail: { zh: 'Canon：回合失败', en: 'Canon: turn failed' },
  notifyBodyOk: { zh: '{name} · 回复 {n}字 · 用时 {t}', en: '{name} · {n} chars · took {t}' },
  notifyMarkOk: { zh: '✓ 回复完成', en: '✓ Reply ready' },
  notifyMarkFail: { zh: '✗ 回合失败', en: '✗ Turn failed' },
  followHoraeTime: { zh: '故事时间跟随 Horae', en: 'Follow Horae story time' },
  followHoraeTimeTip: { zh: '装了 Horae 时：每个新回合从 Horae 记录的时间开始（它每回合都会推算时间）。\n本回合本身经过的时间仍由 Canon Engine 估算。没有 Horae 或 Horae 尚未更新时自动不用。', en: 'With Horae installed: each new turn starts at the story time Horae recorded (it estimates time every turn).\nThe time the turn itself takes is still estimated by Canon Engine. Not used without Horae or while Horae is not up to date.' },
