  leap: { zh: '时间跳跃', en: 'Time leap' },
  leapTip: { zh: '一次快进到指定时间：期间你的角色由 GM 按人设代你过日子，原作事件照常发生，除非你的描述改变了它们。', en: 'Leap to a given time in one reply: the GM lives your character\'s life in between as the Persona would, and canon events happen as in the original unless your description changes them.' },
  leapTitle: { zh: '时间跳跃', en: 'Time leap' },
  leapNow: { zh: '现在', en: 'Now' },
  leapTo: { zh: '跳到', en: 'Leap to' },
  leapToPh: { zh: 'D1500 08:00 或 2004-10-10 08:00（只写日期则为当天 08:00）', en: 'D1500 08:00 or 2004-10-10 08:00 (a date alone lands at 08:00)' },
  leapDesc: { zh: '这段时间里你的角色做什么', en: 'What your character does in this time' },
  leapDescPh: { zh: '和普通回复一样写给 GM，例如：期间我去上大学，交了个朋友……', en: 'Write it like an ordinary reply to the GM, e.g. I go to university and make a friend…' },
  leapInsert: { zh: '填入回复框', en: 'Put in the reply box' },
  leapHint: { zh: '会在回复框里写入 {{time_leap:时间}} 和你的描述，检查后照常发送。手动输入这段指令也一样有效。跨过的原作内容很多时，会按历史包的篇章建议分几章，每章一条回复。跳跃期间 GM 可以替你的角色说话、做决定；落地后的场景恢复你平时的设置。HARD 事件一定会发生，描述与之冲突时这条消息会被打回。', en: 'Writes {{time_leap:time}} and your description into the reply box; check it and send as usual. Typing the directive yourself works the same. A leap across a lot of story is offered in chapters along the arcs of the pack, one reply each. During the leap the GM may speak and decide for your character; the landing scene follows your usual settings. HARD events always happen: a description that rules one out is sent back.' },
  leapBad: { zh: '读不出这个时间。格式同开始时间：D1500 08:00 或 2004-10-10 08:00', en: 'Cannot read this time. Same format as the start time: D1500 08:00 or 2004-10-10 08:00' },
