  conflictMarker: { zh: '与修改后的前文冲突：请修改此消息，或从此处分支后重新生成。', en: 'Conflicts with the edited history: edit this message or branch and regenerate from here.' },
  editIt: { zh: '定位此消息', en: 'Go to message' },
  branchRegen: { zh: '从此处分支并重新生成', en: 'Branch here and regenerate' },
  competing: { zh: '检测到可能与历史引擎冲突的历史/时间线世界书：', en: 'Possible competing history/timeline lorebooks detected:' },
  competingHint: { zh: '请在世界书设置中停用这些“历史事件”世界书；普通设定世界书可以保留。插件不会读取或转换它们。', en: 'Disable these history lorebooks in World Info; ordinary setting lore can stay. The engine does not read or convert them.' },
  gmConflict: { zh: 'GM 角色卡中有“从世界书获取历史”的旧规则。启用后引擎会注入新的时间线规则覆盖它；如需彻底整理，请手动删除那段旧规则。', en: 'The GM card contains an old "history comes from World Info" rule. The engine injects scoped rules that supersede it; remove the old sentence manually for a clean setup.' },
